"""Invoices for Priya's studio: rates, line totals and a rendered invoice.

House rules, kept by the tests in tests/ and audited by check.py:

* Money is rounded half up to two decimals. Not with round(), which rounds half
  to even: round(2.675, 2) is 2.67 where the accountant expects 2.68.
* Billable time rounds up to the next six-minute block, so 61 minutes bills as
  1.1 hours, not 1.0166.
* A line marked nonbillable is still shown on the invoice but adds nothing to
  any total.
* An unknown rate code raises UnknownRate, never KeyError.

A line is a dict: date, task, code, minutes, and optionally nonbillable.
Rows pasted as text ('2026-09-21 dev 185 landing page') are turned into lines
by parse_line(), which raises ValueError on anything else.
"""

from decimal import ROUND_HALF_UP, Decimal

RATES = {"dev": 92.25, "review": 68.25, "admin": 43.50}

LOYALTY = {"review"}


class UnknownRate(Exception):
    pass


def money(amount):
    """Round half up to two decimals."""
    return float(Decimal(str(amount)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def billable_hours(minutes):
    """Minutes as hours, rounded up to the next six-minute block."""
    return -(-int(minutes) // 6) / 10


def rate_for(code):
    if code not in RATES:
        raise UnknownRate(code)
    rate = RATES[code]
    if code in LOYALTY:
        rate *= 0.90
    return money(rate)


def line_total(line):
    return money(billable_hours(line["minutes"]) * rate_for(line["code"]))


def day_total(lines, date):
    """What we bill for one date, across the given lines."""
    return money(
        sum(
            line_total(l)
            for l in lines
            if l["date"] == date and not l.get("nonbillable")
        )
    )


def invoice_total(lines):
    return money(sum(line_total(l) for l in lines if not l.get("nonbillable")))


def summary(lines):
    """Hours per task name, counting every line, billable or not."""
    totals = {}
    for line in lines:
        totals[line["task"]] = totals.get(line["task"], 0.0) + billable_hours(line["minutes"])
    return {task: money(hours) for task, hours in totals.items()}


def render_line(line):
    mark = " (nonbillable)" if line.get("nonbillable") else ""
    return f"{line['task']}\t{billable_hours(line['minutes']):.1f}h\t{line_total(line):.2f}{mark}"


def as_line(row):
    """A pasted text row becomes a line dict; dicts pass through unchanged."""
    return parse_line(row) if isinstance(row, str) else row


def render_invoice(rows):
    """The whole invoice: every line as render_line gives it, then a TOTAL row.

    Accepts line dicts or raw pasted rows; anything else is ValueError via
    parse_line.
    """
    lines = [as_line(r) for r in rows]
    body = "\n".join(render_line(l) for l in lines)
    return f"{body}\nTOTAL\t{invoice_total(lines):.2f}" if lines else f"TOTAL\t{invoice_total(lines):.2f}"


def parse_line(text):
    """'2026-09-21 dev 185 landing page' -> {'date': ..., 'code': ..., 'minutes': ..., 'task': ...}.

    Raises ValueError on anything that isn't a row of a date, a rate code,
    whole-number minutes and a task:  date code minutes task
    """
    parts = text.split()
    if len(parts) < 4:
        raise ValueError(f"not a row, expected 'date code minutes task': {text!r}")
    date, code, minutes, task = parts[0], parts[1], parts[2], " ".join(parts[3:])
    try:
        minutes = int(minutes)
    except ValueError:
        raise ValueError(f"minutes must be a whole number, got {minutes!r}: {text!r}") from None
    return {"date": date, "code": code, "minutes": minutes, "task": task}


def estimate(minutes, code):
    """What a block of work would cost: billable hours for the minutes at the code's rate."""
    return money(billable_hours(minutes) * rate_for(code))

files.tests/test_invoice.py:
import unittest

from invoice import (
    UnknownRate,
    billable_hours,
    invoice_total,
    line_total,
    money,
    rate_for,
    render_line,
)

BILLABLE = {"date": "2026-09-21", "task": "landing page", "code": "dev", "minutes": 25}
NONBILLABLE = {"date": "2026-09-21", "task": "standup", "code": "admin", "minutes": 20, "nonbillable": True}


class HouseRules(unittest.TestCase):
    def test_money_rounds_half_up(self):
        self.assertEqual(money(2.675), 2.68)
        self.assertEqual(line_total(BILLABLE), 46.13)

    def test_hours_round_up_to_six_minute_blocks(self):
        self.assertEqual(billable_hours(1), 0.1)
        self.assertEqual(billable_hours(60), 1.0)
        self.assertEqual(billable_hours(61), 1.1)

    def test_nonbillable_is_shown_but_never_totalled(self):
        self.assertEqual(invoice_total([BILLABLE, NONBILLABLE]), invoice_total([BILLABLE]))
        self.assertIn("standup", render_line(NONBILLABLE))

    def test_unknown_code(self):
        with self.assertRaises(UnknownRate):
            rate_for("design")
